def manage_bank_account():
    """
    Manages bank accounts by taking account type, balance, and transaction type as input,
    and prints the updated balance.
    """

    # Initialize the bank accounts dictionary
    bank_accounts = {}

    while True:
        account_type = input("Enter account type (e.g., Checking, Savings): ").lower()
        if account_type in bank_accounts:
            print(f"Account '{account_type}' already exists. Please choose a different account type.")
            continue

        balance = float(input(f"Enter initial balance for account '{account_type}': $"))
        bank_accounts[account_type] = balance

        transaction_type = input("Enter transaction type (e.g., Deposit, Withdrawal): ").lower()
        transaction_amount = float(input(f"Enter transaction amount for account '{account_type}': $"))

        if transaction_type == "deposit":
            bank_accounts[account_type] += transaction_amount
        elif transaction_type == "withdrawal":
            if bank_accounts[account_type] >= transaction_amount:
                bank_accounts[account_type] -= transaction_amount
            else:
                print(f"Insufficient funds. Current balance is ${bank_accounts[account_type]}.")
        else:
            print("Invalid transaction type. Please try again.")

        print(f"Updated balance for account '{account_type}': ${bank_accounts[account_type]}")

        user_input = input("Do you want to continue? (yes/no): ").lower()
        if user_input != "yes":
            break

    print("Goodbye!")


if __name__ == "__main__":
    manage_bank_account()
```

This program allows users to create new bank accounts, deposit or withdraw money, and view the updated balance for each account.
